def can_transform(k: int, s: str, t: str) -> bool:
    """ Determine if string s can be transformed into string t using at most k operations.

    Available operations:
    - Insert any character at any position in the string
    - Delete any character from the string
    - Replace any character with another character

    Args:
        k: Maximum number of operations allowed (1 <= k <= 20)
        s: Source string (1 <= len(s) <= 500000)
        t: Target string (1 <= len(t) <= 500000)

    Returns:
        True if s can be transformed into t with at most k operations, False otherwise

    >>> can_transform(3, 'abc', 'awtf')
    True
    >>> can_transform(2, 'abc', 'awtf')
    False
    >>> can_transform(17, 'twothousandtwentyfour', 'happynewyear')
    True
    """
    if k < 0:
        return False
    if abs(len(s) - len(t)) > k:
        return False

    # Equal ends can be removed without changing edit distance.
    start = 0
    n, m = len(s), len(t)
    while start < n and start < m and s[start] == t[start]:
        start += 1
    while n > start and m > start and s[n - 1] == t[m - 1]:
        n -= 1
        m -= 1
    s, t = s[start:n], t[start:m]
    n, m = len(s), len(t)
    if not n or not m:
        return max(n, m) <= k
    if max(n, m) <= k:
        return True

    # For each diagonal x-y, retain the furthest source position reachable
    # with the current edit budget, then consume matching characters freely.
    frontier = {0: 0}
    for edits in range(1, k + 1):
        following = {}
        for diagonal, x in frontier.items():
            y = x - diagonal
            if x < n:
                new_diagonal = diagonal + 1  # Delete s[x].
                following[new_diagonal] = max(
                    following.get(new_diagonal, -1), x + 1
                )
            if y < m:
                new_diagonal = diagonal - 1  # Insert t[y].
                following[new_diagonal] = max(
                    following.get(new_diagonal, -1), x
                )
            if x < n and y < m:
                following[diagonal] = max(
                    following.get(diagonal, -1), x + 1
                )

        frontier = {}
        for diagonal, x in following.items():
            y = x - diagonal
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            if x == n and y == m:
                return True
            # Even with perfect matches, this many further edits are needed.
            if abs((n - x) - (m - y)) <= k - edits:
                frontier[diagonal] = x
        if not frontier:
            return False
    return False

