from functools import lru_cache
from math import gcd


# Contains every possible prime power in a zero-free digit sum below 82.
_PRODUCT_MODULUS = 64 * 81 * 25 * 49


@lru_cache(None)
def _next_product(product: int, digit: int) -> int:
    return gcd(product * digit, _PRODUCT_MODULUS)


@lru_cache(None)
def _bad_suffix(remaining: int, digit_sum: int, product: int) -> int:
    """Count zero-free completions whose digit sum does not divide the product."""
    if remaining == 0:
        return int(product % digit_sum != 0)
    return sum(
        _bad_suffix(remaining - 1, digit_sum + digit,
                    _next_product(product, digit))
        for digit in range(1, 10)
    )


def _beautiful_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = [int(char) for char in str(bound)]
    bad = sum(_bad_suffix(length, 0, 1)
              for length in range(1, len(digits)))
    digit_sum = 0
    product = 1
    for index, limit in enumerate(digits):
        remaining = len(digits) - index - 1
        for digit in range(1, limit):
            bad += _bad_suffix(remaining, digit_sum + digit,
                               _next_product(product, digit))
        if limit == 0:
            break
        digit_sum += limit
        product = _next_product(product, limit)
    else:
        bad += int(product % digit_sum != 0)
    # Every positive number containing a zero is automatically beautiful.
    return bound - bad


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive interval [l, r].

    A number is beautiful if its digit product is divisible by its digit sum.
    The bounds satisfy 1 <= l <= r < 10**9.

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _beautiful_up_to(r) - _beautiful_up_to(l - 1)

