def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements having at least k reducible contiguous substrings.

    A nonempty string is reducible precisely when its A, B, and C counts
    have the same parity. Return the number of replacements modulo 998244353.

    Args:
        n: Length of s, between 1 and 50.
        k: Required number of good substrings.
        s: A string over A, B, C, and '?'.

    >>> count_good_string_replacements(4, 2, 'A?AB')
    1
    >>> count_good_string_replacements(1, 0, 'A')
    1
    >>> count_good_string_replacements(2, 1, 'CC')
    1
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count('?'), mod)

    # Map A, B, C to the three nonzero elements of the XOR group.
    # A good substring has equal prefix XORs at its endpoints.
    # Adjacent prefixes differ, so the greatest possible collision count
    # comes from alternating between two states.
    if k > n * n // 4:
        return 0

    labels = {'A': (1,), 'B': (2,), 'C': (3,), '?': (1, 2, 3)}
    # Store counts of prefix states 0, 1, 2 and the current XOR state.
    # The count of state 3 is implied by the number of prefixes processed.
    dp = {(1, 0, 0, 0): 1}
    for ch in s:
        following = {}
        choices = labels[ch]
        for (a, b, c, current), ways in dp.items():
            for label in choices:
                target = current ^ label
                if target == 0:
                    state = (a + 1, b, c, target)
                elif target == 1:
                    state = (a, b + 1, c, target)
                elif target == 2:
                    state = (a, b, c + 1, target)
                else:
                    state = (a, b, c, target)
                following[state] = (following.get(state, 0) + ways) % mod
        dp = following

    total = 0
    prefix_count = len(s) + 1
    for (a, b, c, current), ways in dp.items():
        d = prefix_count - a - b - c
        good = (a * (a - 1) + b * (b - 1) +
                c * (c - 1) + d * (d - 1)) // 2
        if good >= k:
            total += ways
    return total % mod

