from math import isqrt


def _make_signatures():
    tables = [[0]]
    for width in range(1, 5):
        previous = tables[-1]
        tables.append([
            previous[value // 10] + (1 << (4 * (value % 10)))
            for value in range(10 ** width)
        ])
    return tables


_SIGNATURES = _make_signatures()


def count_square_permutations(n: int, s: str) -> int:
    """Count distinct squares whose n-digit, zero-padded form permutes s.

    Leading zeros are permitted. For example, '010' forms the squares 1
    and 100, while '4320' forms 324 and 2304.
    """
    target = sum(1 << (4 * int(digit)) for digit in s)
    digit_sum = sum(map(int, s)) % 9
    residues = [r for r in range(9) if r * r % 9 == digit_sum]
    if not residues:
        return 0

    limit = isqrt(int("".join(sorted(s, reverse=True))))
    # A four-bit field per digit holds every frequency, since n <= 13.
    # Fixed-width chunk signatures include all necessary leading zeros.
    blocks = _SIGNATURES[4]
    top = _SIGNATURES[(n - 1) % 4 + 1]
    answer = 0
    if n <= 4:
        for residue in residues:
            for root in range(residue, limit + 1, 9):
                if top[root * root] == target:
                    answer += 1
    elif n <= 8:
        for residue in residues:
            for root in range(residue, limit + 1, 9):
                square = root * root
                if blocks[square % 10000] + top[square // 10000] == target:
                    answer += 1
    elif n <= 12:
        for residue in residues:
            for root in range(residue, limit + 1, 9):
                square = root * root
                low = blocks[square % 10000]
                square //= 10000
                if low + blocks[square % 10000] + top[square // 10000] == target:
                    answer += 1
    else:
        for residue in residues:
            for root in range(residue, limit + 1, 9):
                square = root * root
                low = blocks[square % 10000]
                square //= 10000
                low += blocks[square % 10000]
                square //= 10000
                if low + blocks[square % 10000] + top[square // 10000] == target:
                    answer += 1
    return answer

