def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper completions of a grid over '1', '2', '3', and '?'.

    Adjacent edge-sharing cells must have different digits. Return the number
    of completions modulo 998244353. The grid has at most 200 cells.
    """
    mod = 998244353
    # The frontier is exponential only in the smaller dimension (at most 14).
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Store frontier colors in two bits each. When visiting a cell, its slot
    # holds its upper neighbor, and the previous slot holds its left neighbor.
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            shift = 2 * c
            clear = ~(3 << shift)
            left_shift = shift - 2
            ch = grid[r][c]
            choices = (1, 2, 3) if ch == "?" else (int(ch),)
            following = {}
            for state, count in dp.items():
                above = (state >> shift) & 3
                left = (state >> left_shift) & 3 if c else 0
                base = state & clear
                for color in choices:
                    if color != above and color != left:
                        new_state = base | (color << shift)
                        following[new_state] = (following.get(new_state, 0) + count) % mod
            dp = following
            if not dp:
                return 0
    return sum(dp.values()) % mod

