def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    """Return the fewest adjacent-stone-pair moves from s to t.

    The two empty cells initially follow the n stones and must also follow
    the stones in the target. A move preserves the order of the moved pair.
    Return -1 when no sequence of legal moves reaches the target.
    """
    if s == t:
        return 0
    if s.count('W') != t.count('W'):
        return -1

    # A state contains the white-stone bitmask and the index of the first
    # empty cell. Black stones occupy every remaining nonempty cell.
    start_mask = sum(1 << i for i, c in enumerate(s) if c == 'W')
    target_mask = sum(1 << i for i, c in enumerate(t) if c == 'W')
    start = (start_mask << 4) | n
    target = (target_mask << 4) | n

    # A source pair cannot overlap either empty cell.
    sources = [tuple(i for i in range(n + 1)
                     if i + 1 < gap or i > gap + 1)
               for gap in range(n + 1)]
    front = {start}
    back = {target}
    forward_dist = {start: 0}
    backward_dist = {target: 0}

    # Every move is reversible, so either end can supply the next BFS layer.
    while front and back:
        if len(front) > len(back):
            front, back = back, front
            forward_dist, backward_dist = backward_dist, forward_dist
        next_front = set()
        for state in front:
            mask, gap = state >> 4, state & 15
            distance = forward_dist[state] + 1
            for source in sources[gap]:
                pair = (mask >> source) & 3
                moved_mask = (mask ^ (pair << source)) | (pair << gap)
                neighbor = (moved_mask << 4) | source
                if neighbor in forward_dist:
                    continue
                if neighbor in backward_dist:
                    return distance + backward_dist[neighbor]
                forward_dist[neighbor] = distance
                next_front.add(neighbor)
        front = next_front
    return -1

