def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether the Levenshtein distance between s and t is at most k.

    An operation inserts, deletes, or replaces one character. The supported
    bounds are 1 <= k <= 20 and string lengths up to 500000.
    """
    if abs(len(s) - len(t)) > k:
        return False
    if s == t:
        return True

    # Equal ends do not affect edit distance.
    start = 0
    limit = min(len(s), len(t))
    while start < limit and s[start] == t[start]:
        start += 1
    end_s, end_t = len(s), len(t)
    while end_s > start and end_t > start and s[end_s - 1] == t[end_t - 1]:
        end_s -= 1
        end_t -= 1
    s, t = s[start:end_s], t[start:end_t]
    n, m = len(s), len(t)
    if max(n, m) <= k:
        return True
    if not n or not m:
        return False

    # For each diagonal d = i - j, retain the furthest source position
    # reachable with the current number of edits, followed by free matches.
    frontier = {0: 0}
    for _ in range(k):
        following = {}
        for diagonal, i in frontier.items():
            j = i - diagonal
            if i < n and j < m:
                following[diagonal] = max(following.get(diagonal, -1), i + 1)
            if i < n:
                d = diagonal + 1
                following[d] = max(following.get(d, -1), i + 1)
            if j < m:
                d = diagonal - 1
                following[d] = max(following.get(d, -1), i)

        for diagonal, i in following.items():
            j = i - diagonal
            while i < n and j < m and s[i] == t[j]:
                i += 1
                j += 1
            if i == n and j == m:
                return True
            following[diagonal] = i
        frontier = following
    return False

