def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum the products of all positive good sequences, modulo 998244353.

    Adjacent reduced ratios have numerator times denominator a[i], and
    the gcd of the entire sequence is one.  Constraints: 2 <= n <= 1000,
    len(a) == n - 1, and 1 <= a[i] <= 1000.
    """
    mod = 998244353

    # For each prime, adjacent exponents differ by exactly its exponent
    # in a[i].  Choices for different primes are independent.
    factors = {}
    for i, value in enumerate(a):
        p = 2
        while p * p <= value:
            if value % p == 0:
                exponent = 0
                while value % p == 0:
                    value //= p
                    exponent += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = exponent
            p += 1
        if value > 1:
            if value not in factors:
                factors[value] = [0] * (n - 1)
            factors[value][i] = 1

    answer = 1
    for prime, steps in factors.items():
        limit = max(sum(steps), n * max(steps))
        powers = [1] * (limit + 1)
        for h in range(1, limit + 1):
            powers[h] = powers[h - 1] * prime % mod

        # dp[h] sums prime**(sum of exponents) for prefixes whose
        # minimum exponent is zero and whose last exponent is h.
        dp = [1]
        for length, step in enumerate(steps, 1):
            if step == 0:
                dp = [weight * powers[h] % mod
                      for h, weight in enumerate(dp)]
                continue

            nxt = [0] * (len(dp) + step)
            for h, weight in enumerate(dp):
                if not weight:
                    continue
                higher = h + step
                nxt[higher] = (nxt[higher] + weight * powers[higher]) % mod
                if h >= step:
                    lower = h - step
                    nxt[lower] = (nxt[lower] + weight * powers[lower]) % mod
                else:
                    # A new minimum shifts all previous exponents up;
                    # the newly appended exponent becomes zero.
                    shift = step - h
                    nxt[0] = (nxt[0] + weight * powers[length * shift]) % mod
            dp = nxt
        answer = answer * (sum(dp) % mod) % mod

    return answer

