from functools import lru_cache
from itertools import combinations_with_replacement
from math import factorial, prod


@lru_cache(None)
def _patterns(length):
    """Beautiful multisets of nonzero digits and their permutation counts."""
    patterns = []
    for digits in combinations_with_replacement(range(1, 10), length):
        if prod(digits) % sum(digits):
            continue
        counts = tuple(digits.count(d) for d in range(1, 10))
        ways = factorial(length)
        for count in counts:
            ways //= factorial(count)
        patterns.append((counts, ways))
    return tuple(patterns)


@lru_cache(None)
def _total(length):
    return sum(ways for _, ways in _patterns(length))


def _count_up_to(n):
    if n <= 0:
        return 0
    digits = tuple(map(int, str(n)))
    length = len(digits)

    # Subtract all zero-free integers; integers with a zero are beautiful.
    nonzero = sum(9 ** k for k in range(1, length))
    for i, digit in enumerate(digits):
        nonzero += max(0, digit - 1) * 9 ** (length - i - 1)
        if digit == 0:
            break
    else:
        nonzero += 1
    answer = n - nonzero + sum(_total(k) for k in range(1, length))

    # Rank the bound among the distinct permutations of each valid multiset.
    for initial_counts, initial_ways in _patterns(length):
        counts = list(initial_counts)
        ways = initial_ways
        remaining = length
        for digit in digits:
            if digit == 0:
                break
            smaller = sum(counts[:digit - 1])
            answer += ways * smaller // remaining
            available = counts[digit - 1]
            if not available:
                break
            ways = ways * available // remaining
            counts[digit - 1] -= 1
            remaining -= 1
        else:
            answer += 1
    return answer


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive range [l, r].

    A number is beautiful if its digit product is divisible by its digit sum.
    Constraints: 1 <= l <= r < 10**9.

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

