from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Find the largest subtree whose degrees are 1 or 4, with a degree-4 vertex.

    Vertices are numbered 1 through n; return -1 when no such subtree exists.
    Runs in O(n) time and space without recursion.
    """
    adjacency = [[] for _ in range(n + 1)]
    for u, v in edges:
        adjacency[u].append(v)
        adjacency[v].append(u)

    parent = [0] * (n + 1)
    order = [1]
    for v in order:
        for u in adjacency[v]:
            if u != parent[v]:
                parent[u] = v
                order.append(u)

    # down[v] includes v and assumes its edge to its parent is selected.
    # Thus v is either a leaf, or has exactly three selected children.
    down = [1] * (n + 1)
    answer = -1
    for v in reversed(order):
        a = b = c = d = 0
        for u in adjacency[v]:
            if u == parent[v]:
                continue
            value = down[u]
            if value >= a:
                a, b, c, d = value, a, b, c
            elif value >= b:
                b, c, d = value, b, c
            elif value >= c:
                c, d = value, c
            elif value > d:
                d = value
        if c:
            down[v] = 1 + a + b + c
            # The highest selected vertex may be the parent, used as a leaf.
            if parent[v]:
                answer = max(answer, down[v] + 1)
        if d:
            # Otherwise the highest selected vertex has four children.
            answer = max(answer, 1 + a + b + c + d)
    return answer

