from typing import List


def count_valid_strings(K: int, C: List[int]) -> int:
    """Count nonempty uppercase strings of length at most K with letter caps.

    Each letter i may occur at most C[i] times. Return the count modulo
    998244353. K is at most 1000 and C contains 26 nonnegative integers.
    """
    mod = 998244353
    limit = min(K, sum(C))
    if limit == 0:
        return 0

    factorial = [1] * (limit + 1)
    for n in range(1, limit + 1):
        factorial[n] = factorial[n - 1] * n % mod
    inverse_factorial = [1] * (limit + 1)
    inverse_factorial[limit] = pow(factorial[limit], mod - 2, mod)
    for n in range(limit, 0, -1):
        inverse_factorial[n - 1] = inverse_factorial[n] * n % mod

    # Unrestricted letters together contribute exp(unrestricted * x).
    unrestricted = sum(cap >= limit for cap in C)
    if unrestricted:
        coefficients = [1] * (limit + 1)
        power = 1
        for n in range(1, limit + 1):
            power = power * unrestricted % mod
            coefficients[n] = power * inverse_factorial[n] % mod
    else:
        coefficients = [1]

    # Multiply the exponential generating functions sum(x**j / j!).
    # The coefficient of x**n, multiplied by n!, counts arrangements.
    for cap in sorted(cap for cap in C if 0 < cap < limit):
        degree = min(limit, len(coefficients) - 1 + cap)
        updated = [0] * (degree + 1)
        for old_degree, coefficient in enumerate(coefficients):
            for added in range(min(cap, limit - old_degree) + 1):
                n = old_degree + added
                updated[n] = (
                    updated[n] + coefficient * inverse_factorial[added]
                ) % mod
        coefficients = updated

    return sum(
        coefficient * factorial[n]
        for n, coefficient in enumerate(coefficients) if n
    ) % mod

