from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Return the shortest distance in the alternating horizontal/vertical tiling.

    Coordinates identify the tile containing the cell centre (x+.5, y+.5).
    All arithmetic is integral, including floor division for negative cells.
    """
    def tile(x, y):
        i, u = divmod(x, K)
        j, v = divmod(y, K)
        return i, j, v if (i + j) % 2 == 0 else u

    start, target = tile(S_x, S_y), tile(T_x, T_y)

    def nearby(source):
        # Only the two end strips of an intermediate square are needed.
        # A crossing can select either of them; other strips cannot provide
        # a shorter continuation. Keep the source strip as well.
        distances = {source: 0}
        queue = [(0, source)]
        ends = (0, K - 1)
        anchors = []
        while queue:
            d, state = heappop(queue)
            if distances[state] != d:
                continue
            i, j, r = state
            if r in ends:
                anchors.append((i, j, r, d))
            edges = [((i, j, e), abs(r - e)) for e in ends]
            if (i + j) % 2 == 0:
                edges.extend((((i - 1, j, K - 1), 1),
                              ((i + 1, j, 0), 1)))
                if r == 0:
                    edges.extend(((i, j - 1, e), 1) for e in ends)
                if r == K - 1:
                    edges.extend(((i, j + 1, e), 1) for e in ends)
            else:
                edges.extend((((i, j - 1, K - 1), 1),
                              ((i, j + 1, 0), 1)))
                if r == 0:
                    edges.extend(((i - 1, j, e), 1) for e in ends)
                if r == K - 1:
                    edges.extend(((i + 1, j, e), 1) for e in ends)
            for nxt, weight in edges:
                nd = d + weight
                if nd <= 4 and nd < distances.get(nxt, 5):
                    distances[nxt] = nd
                    heappush(queue, (nd, nxt))
        return anchors

    if start == target:
        return 0
    answer = float("inf")
    if start[:2] == target[:2]:
        # Leaving through a long side and returning changes any strip in
        # two moves, which can beat walking between strips.
        answer = min(abs(start[2] - target[2]), 2)

    # Equal end-strip states in equal-orientation squares have distance
    # 2*max(dx,dy), except for K=2, where each remaining pair of axial
    # steps costs three rather than four. Diagonal steps always cost two.
    # A shortest route can use such a bulk segment after/before at most
    # four local moves; these local moves also cover nearby endpoints.
    left, right = nearby(start), nearby(target)
    for i, j, r, d in left:
        for x, y, s, e in right:
            if r != s or (i + j - x - y) % 2:
                continue
            dx, dy = abs(i - x), abs(j - y)
            large, small = max(dx, dy), min(dx, dy)
            bulk = (3 * large + small) // 2 if K == 2 else 2 * large
            answer = min(answer, d + bulk + e)
    return int(answer)
